"use client";

import { forwardRef } from "react";
import { Button, type ButtonProps } from "../button/button";
import { gradientButtonDefaults, type GradientButtonSpecProps } from "../generated/gradient-button.types";
import { cx } from "../utils/cx";

export interface GradientButtonProps extends GradientButtonSpecProps, Omit<ButtonProps, keyof GradientButtonSpecProps> {}

const defaultColors = ["var(--rd-color-action-primary)", "var(--rd-color-feedback-warning)", "var(--rd-color-feedback-info)"];

/**
 * A button with a colour that travels around its edge. The label sits on the normal button
 * surface, so its contrast is the plain Button's, whatever the colours do. Builds on Button.
 */
export const GradientButton = forwardRef<HTMLButtonElement, GradientButtonProps>(function GradientButton(
  {
    children,
    colors = defaultColors,
    duration = gradientButtonDefaults.duration,
    borderWidth = gradientButtonDefaults.borderWidth,
    isPaused = gradientButtonDefaults.isPaused,
    variant = "secondary",
    isDisabled,
    className,
    ...rest
  },
  ref,
) {
  const ring = [...colors, colors[0]].join(", ");
  return (
    <span
      data-rdm-paused={isPaused || isDisabled || undefined}
      className={cx("rdm-gradient inline-flex rounded-[var(--rd-radius-control)]", isDisabled && "opacity-50")}
      style={{
        padding: borderWidth,
        backgroundImage: `conic-gradient(from var(--rdm-angle), ${ring})`,
        ["--rdm-d" as string]: `${duration}s`,
      }}
    >
      <Button
        {...rest}
        ref={ref}
        variant={variant}
        isDisabled={isDisabled}
        className={cx("!border-transparent", className)}
        style={{ borderRadius: `calc(var(--rd-radius-control) - ${borderWidth}px)` }}
      >
        {children}
      </Button>
    </span>
  );
});

// Generated by rdloom codegen from specs/gradient-button.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const gradientButtonVariantValues = ["primary", "secondary", "ghost", "danger"] as const;
export const gradientButtonSizeValues = ["sm", "md", "lg"] as const;

/** A button with a colour that travels around its edge. The label sits on the normal button surface, so its contrast is the plain Button's. Builds on Button. */
export interface GradientButtonSpecProps {
  /**
   * Button label. Icon-only buttons must pass aria-label instead.
   */
  children: ReactNode;
  /**
   * Visual emphasis, as on Button.
   * @default "secondary"
   */
  variant?: "primary" | "secondary" | "ghost" | "danger";
  /**
   * Height, padding and font size, as on Button.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Colours of the edge, any CSS colours. Two or more.
   */
  colors?: readonly string[];
  /**
   * Seconds for the colour to travel once around.
   * @default 3
   */
  duration?: number;
  /**
   * Thickness of the coloured edge in pixels.
   * @default 2
   */
  borderWidth?: number;
  /**
   * Stops the animation. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
  /**
   * Prevents interaction and dims the button.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Shows a spinner and blocks presses; the pending state is announced.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Called when the button is pressed by mouse, touch or keyboard.
   */
  onPress?: () => void;
}

export const gradientButtonDefaults = {
  variant: "secondary",
  size: "md",
  duration: 3,
  borderWidth: 2,
  isPaused: false,
  isDisabled: false,
  isLoading: false,
} as const;

export const gradientButtonMeta = {
  "name": "GradientButton",
  "version": "0.1.0",
  "status": "experimental",
  "role": "button"
} as const;
